@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&display=swap');
:root{--bg:#111412;--panel:#171b18;--panel2:#1d221e;--ink:#e9e9df;--muted:#8a9087;--faint:#596158;--line:#2c332e;--acid:#d4ed72;--orange:#e79b68;--mono:'DM Mono',monospace;--sans:'Manrope',sans-serif}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:var(--sans);min-height:100vh;background-image:radial-gradient(ellipse at 48% 45%,rgba(51,64,51,.13),transparent 55%)}button{font:inherit;color:inherit}.app-shell{max-width:1480px;margin:auto;padding:0 56px}.topbar{height:74px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;font:10px var(--mono);letter-spacing:.13em;color:#a2a89d}.brand{display:flex;align-items:center;gap:12px;color:var(--ink);text-decoration:none;font-weight:500;letter-spacing:.18em}.brand-mark{font-size:22px;color:var(--acid)}.top-center{display:flex;align-items:center;gap:9px}.top-center b{color:var(--ink);font-weight:500}.live-dot,.caption-dot{width:6px;height:6px;border-radius:50%;background:var(--acid);box-shadow:0 0 10px #d4ed7299}.top-divider{height:15px;width:1px;background:var(--line);margin:0 8px}.weather{color:var(--acid);font-size:17px}.icon-button{width:34px;height:34px;border:1px solid var(--line);background:transparent;color:var(--acid);border-radius:50%;cursor:pointer;font-size:15px}.icon-button:hover{border-color:var(--acid)}.dashboard{display:grid;grid-template-columns:minmax(205px,.83fr) minmax(390px,1.45fr) minmax(248px,.96fr);gap:clamp(28px,4vw,70px);padding:48px 0 42px;align-items:start}.eyebrow{display:flex;align-items:center;gap:12px;color:#92988e;font:10px var(--mono);letter-spacing:.15em;white-space:nowrap}.eyebrow .line{height:1px;background:var(--line);flex:1}.left-panel h1,.right-panel h2{font-size:clamp(34px,3vw,48px);line-height:1.04;letter-spacing:-.055em;font-weight:600;margin:25px 0 12px}.left-panel h1 em,.right-panel h2 em{font-weight:400;color:var(--acid);font-family:Georgia,serif;letter-spacing:-.07em}.intro{font-size:12px;line-height:1.8;color:#92988e;max-width:235px;margin:0 0 28px}.stats-card{background:var(--panel);border:1px solid #252b26;border-radius:5px;padding:7px 15px}.stat-row{height:45px;display:grid;grid-template-columns:22px 1fr auto;align-items:center;gap:8px;border-bottom:1px solid #252b26;color:#9da398;font-size:11px}.stat-row:last-child{border:0}.stat-row strong{font:500 14px var(--mono);color:var(--ink)}.stat-row strong small{font-size:10px;color:var(--muted)}.stat-icon{font-size:13px;text-align:center}.stone-icon{color:var(--acid)}.sparkle{color:var(--orange)}.depth-icon{color:#8e9d8d}.progress-block{margin-top:27px}.progress-label{display:flex;justify-content:space-between;color:#92988e;font:9px var(--mono);letter-spacing:.07em}.progress-label span:last-child{color:var(--ink)}.progress-track{height:4px;background:#282e29;margin:11px 0 9px;border-radius:3px;overflow:hidden}.progress-track i{display:block;width:0;height:100%;background:var(--acid);transition:width .35s}.progress-block p{margin:0;color:#7e867c;font-size:10px}.note-card,.tip-card{display:flex;gap:12px;border-top:1px solid var(--line);margin-top:28px;padding-top:16px}.note-mark,.tip-icon{color:var(--acid);font-size:16px}.note-card b,.tip-card b{font:9px var(--mono);letter-spacing:.12em;color:#b9c0b5}.note-card p,.tip-card p{color:#828a80;font-size:10px;line-height:1.7;margin:6px 0 0}.mine-panel{background:#171b18;border:1px solid #2b312c;border-radius:5px;padding:19px 21px 16px;box-shadow:0 16px 70px #0002;position:relative}.scene-top{display:flex;align-items:center;justify-content:space-between;font:9px var(--mono);letter-spacing:.1em;color:#888f85}.scene-label b{color:var(--ink);font-weight:400}.rarity{margin-left:10px;color:var(--acid);font-size:8px;border:1px solid #39452d;padding:4px 6px;border-radius:2px}.depth-chip{border:1px solid #303831;padding:6px 8px;border-radius:3px;color:#8e968a}.depth-chip span{color:var(--acid);font-size:14px;vertical-align:-1px}.depth-chip b{color:var(--ink);font-weight:400}.rock-stage{height:clamp(290px,32vw,410px);max-height:410px;position:relative;margin:10px -8px 0;overflow:hidden;display:flex;justify-content:center;align-items:center;cursor:pointer;touch-action:manipulation}.ambient-glow{position:absolute;width:72%;height:72%;border-radius:50%;background:radial-gradient(ellipse,rgba(163,176,122,.105),transparent 68%);filter:blur(12px)}.stage-grid{position:absolute;inset:0;opacity:.22;background-image:linear-gradient(#30383055 1px,transparent 1px),linear-gradient(90deg,#30383055 1px,transparent 1px);background-size:45px 45px;mask-image:radial-gradient(ellipse,black,transparent 77%)}.rock-shadow{position:absolute;width:53%;height:14px;border-radius:50%;bottom:49px;background:#070a08;filter:blur(14px);opacity:.86}.rock-stage canvas{position:relative;width:min(94%,440px);height:auto;max-height:100%;z-index:2;filter:drop-shadow(0 16px 12px #080a08a6);transition:transform .12s;cursor:pointer}.rock-stage canvas.hit{animation:hit .23s ease-out}.rock-stage.shake{animation:shake .22s ease-out}.hit-flash{position:absolute;z-index:3;inset:10%;pointer-events:none;background:radial-gradient(circle at center,rgba(237,245,191,.5),transparent 55%);opacity:0}.hit-flash.show{animation:flash .28s ease-out}.crack-overlay{position:absolute;inset:0;z-index:4;pointer-events:none}.float-layer{position:absolute;inset:0;z-index:6;pointer-events:none}.stage-caption{position:absolute;z-index:5;bottom:15px;left:8px;display:flex;align-items:center;gap:9px;color:#c4c9bd;font-size:10px}.caption-dot{width:5px;height:5px}.caption-sep{color:#555e53}.stage-caption span:last-child{color:#7c857a}.tap-hint{position:absolute;right:9px;bottom:14px;z-index:5;color:#7d867b;font:8px var(--mono);letter-spacing:.08em;opacity:.78}.tap-hint span{color:var(--acid);margin-right:4px}.rock-status{border-top:1px solid #2b312c;padding-top:13px}.hp-heading{display:flex;justify-content:space-between;color:#9ba297;font:9px var(--mono);letter-spacing:.1em}.hp-heading span:last-child{color:var(--ink);font-size:10px}.hp-heading i{font-style:normal;color:#7d857a}.hp-track{height:6px;margin-top:8px;position:relative;background:#2c332e;border-radius:4px;overflow:hidden}.hp-track>div{height:100%;width:100%;background:linear-gradient(90deg,#b8d85c,#d5eb7b);border-radius:4px;transition:width .2s}.hp-ticks{position:absolute;inset:0;display:flex;justify-content:space-evenly}.hp-ticks i{height:100%;width:1px;background:#171b18;opacity:.55}.tool-row{display:flex;justify-content:space-between;align-items:center;padding:11px 0 0}.tool-info{display:flex;align-items:center;gap:9px;color:#818a80;font:8px var(--mono);letter-spacing:.08em}.pickaxe{font-size:16px;color:#bbc994}.tool-info b{display:block;color:#d4d7cc;font:10px var(--sans);letter-spacing:0;margin-top:3px}.power-badge{border:1px solid #333c31;border-radius:2px;padding:5px 7px;color:#899386;font:8px var(--mono);letter-spacing:.08em}.power-badge b{color:var(--acid);font-weight:500;margin-left:4px}.strike-button{width:100%;border:0;border-radius:3px;background:var(--acid);color:#182014;height:46px;display:flex;align-items:center;justify-content:center;gap:12px;font:800 11px var(--sans);letter-spacing:.14em;cursor:pointer;margin-top:13px;transition:transform .1s,background .2s}.strike-button:hover{background:#e2f68f}.strike-button:active{transform:translateY(2px) scale(.99)}.strike-icon{font-size:17px}.strike-button kbd{font:8px var(--mono);background:#b4cf5f;padding:4px 6px;border-radius:2px;color:#45502c}.under-button{display:flex;justify-content:space-between;margin-top:9px;color:#788176;font-size:9px}.combo-display{font:8px var(--mono);letter-spacing:.08em;color:#8b9388}.combo-display b{color:var(--orange);font-weight:500}.right-panel h2{font-size:36px;margin:24px 0 19px}.upgrade-list{display:flex;flex-direction:column;gap:9px}.upgrade-card{background:var(--panel);border:1px solid #2a312b;border-radius:4px;padding:10px;display:grid;grid-template-columns:47px minmax(0,1fr);gap:11px;transition:border-color .2s,opacity .2s}.upgrade-card:hover{border-color:#495440}.upgrade-card.disabled{opacity:.55}.upgrade-art{height:48px;border-radius:3px;background:#252d24;display:grid;place-items:center;position:relative;overflow:hidden}.upgrade-art:after{content:'';position:absolute;inset:auto -12px -18px;width:65px;height:32px;background:#52613a4a;filter:blur(10px);border-radius:50%}.upgrade-art span{position:relative;z-index:1;font-size:22px;color:#c8df7b}.glove-art{background:#2c2721}.glove-art span{color:#d39a6f}.lamp-art{background:#282b24}.lamp-art span{color:#e9d887}.upgrade-copy{min-width:0}.upgrade-title{font-size:10px;font-weight:700;white-space:nowrap}.upgrade-level{font:8px var(--mono);color:#8e978c;margin-left:3px}.upgrade-copy p{font-size:9px;color:#7e877d;margin:4px 0 8px;white-space:nowrap}.upgrade-bottom{display:flex;align-items:center;justify-content:space-between}.cost{font:10px var(--mono);color:#d8e58e}.cost i{font-style:normal;color:var(--acid);font-size:9px;margin-right:5px}.buy-button{background:#252d25;border:1px solid #394232;border-radius:2px;padding:5px 6px;color:#c0d77b;font:8px var(--mono);letter-spacing:.03em;cursor:pointer;white-space:nowrap}.buy-button span{font-size:11px;margin-left:3px}.buy-button:hover:not(:disabled){background:#34402c}.buy-button:disabled{opacity:.38;cursor:not-allowed}.tip-card{margin-top:23px;border:1px solid #2d342d;background:#171b18;border-radius:3px;padding:11px;gap:9px}.tip-icon{font-size:15px}.tip-card p{margin-top:4px}.reset-button{display:block;margin:16px auto 0;border:0;background:none;color:#687168;font:9px var(--mono);cursor:pointer}.reset-button:hover{color:#c3cabc}.footer{border-top:1px solid var(--line);padding:15px 0 20px;display:flex;justify-content:space-between;color:#657066;font:8px var(--mono);letter-spacing:.1em}.footer i{font-style:normal;color:#a0ab90}.footer b{color:var(--acid);font-size:7px;margin-left:5px}.toast{position:fixed;left:50%;bottom:24px;transform:translate(-50%,20px);padding:10px 15px;background:#d4ed72;color:#1b2416;border-radius:3px;font:10px var(--mono);opacity:0;pointer-events:none;transition:all .22s;z-index:20;box-shadow:0 6px 25px #0005}.toast.show{opacity:1;transform:translate(-50%,0)}.float-text{position:absolute;font:700 15px var(--mono);color:#e5f38b;text-shadow:0 2px 6px #000;animation:floatup .8s ease-out forwards;white-space:nowrap}.float-text.crit{font-size:19px;color:#f0a66f}.debris{position:absolute;width:5px;height:5px;background:#d4ed72;animation:debris .5s ease-out forwards;border-radius:1px}@keyframes hit{0%{transform:translateX(0) scale(1)}25%{transform:translateX(4px) scale(.97)}55%{transform:translateX(-3px) scale(1.015)}100%{transform:translateX(0) scale(1)}}@keyframes shake{20%{transform:translateX(-4px)}50%{transform:translateX(4px)}80%{transform:translateX(-2px)}}@keyframes flash{0%{opacity:.75}100%{opacity:0}}@keyframes floatup{0%{opacity:0;transform:translate(-50%,0) scale(.8)}20%{opacity:1}100%{opacity:0;transform:translate(-50%,-55px) scale(1.08)}}@keyframes debris{0%{opacity:1;transform:translate(0,0) scale(1)}100%{opacity:0;transform:translate(var(--dx),var(--dy)) scale(.1)}}
